import { dayjs } from '../../lib/datetime.js';

/**
 * BTC/JPY 1時間足の実データ fixture（issue #242 の回帰用。「実データ D」）。
 *
 * `detect_patterns('btc_jpy', '1hour', 365)` が **実際にスキャンする窓そのもの**
 * （`analyze_indicators('btc_jpy', '1hour', 365)` の `chart.candles` を
 * `chart.meta.pastBuffer` で slice した後の 365 本）を bitbank public API から取得して
 * 凍結したもの。取得日 2026-09-05。取得手順は `btc_jpy_1hour_2026_08.ts`（実データ B）/
 * `btc_jpy_1hour_2026_09.ts`（実データ C）と同じ。
 *
 * | | 値 |
 * |---|---|
 * | pair / type | `btc_jpy` / `1hour` |
 * | 期間 | `2026-08-21T04:00:00.000Z` 〜 `2026-09-05T08:00:00.000Z` |
 * | 本数 | 365（`detect_patterns` の `limit` 上限） |
 * | 連続性 | 1 時間刻みで欠損 0（`START + i * 3600000` で `isoTime` を再現できる） |
 *
 * ## なぜ実データ C を伸ばさず別ファイルにしたか
 *
 * **実データ B / C は 1 バイトも変えていない。** C（`2026-08-20T09:00Z` 〜 `2026-09-04T13:00Z`）は
 * #227 Phase 1 の再計測が依存する窓で、末尾を伸ばすと relaxed フォールバックの発火可否が
 * 黙って変わる（C 側の docstring）。B は #146 の回帰がその窓に依存する。**別の窓として並置し、
 * 集計もプールせず別建ての表で見る**（#219 の教訓）。
 *
 * ## 実データ C との重なり（取得手順の同一性の検算）
 *
 * 両者は `2026-08-21T04:00Z` 〜 `2026-09-04T13:00Z` の **346 本が重なる**（本 fixture の idx `i` が
 * 実データ C の idx `i + 19`）。重複区間の `[open, high, low, close]` を突き合わせた結果:
 *
 * | | 結果 |
 * |---|---|
 * | 一致 | **345 / 346 本（全 4 値）** |
 * | 相違 | **1 本だけ**——実データ C の**末尾** idx 364（`2026-09-04T13:00Z`） |
 *
 * 相違の中身は `open` が一致し `high` / `low` / `close` が違う:
 *
 * | | open | high | low | close |
 * |---|---:|---:|---:|---:|
 * | 実データ C idx 364 | 12,389,609 | 12,415,517 | 12,378,134 | 12,414,587 |
 * | 本 fixture idx 345 | 12,389,609 | **12,421,212** | **12,318,196** | **12,387,313** |
 *
 * **C の末尾は取得時点の未確定足**（2026-09-04 の取得で、その 1 時間がまだ閉じていない）。
 * 本 fixture は同じ 1 時間の確定後の値を持つ。高安が広がり終値が動くのは未確定足の性質で、
 * **取得手順の不一致ではない**（他 345 本が全 4 値一致していることがその根拠）。
 * 未確定足を含む窓は実データ C 側にそのまま残してある——**過去の計測の再現性を壊さないため**。
 *
 * ## 起票時のライブ実例（issue #242 本文の再現手順そのもの）
 *
 * issue は `detect_patterns('btc_jpy', '1hour', 72)` を 2026-09-05 に実行した結果を挙げている。
 * その窓は `2026-09-02T04:00Z` 〜 `2026-09-05T03:00Z` で、**本 fixture の idx 288〜359**
 * （`candles.slice(288, 360)`）にあたる。**issue 本文の idx に一律 +288 すると本 fixture の idx** になる。
 *
 * `[open, high, low, close]` の **close がピボットの `price`**（`detectSwingPoints` は
 * 判定を high/low、格納を close で行う。`swing.ts` の `Pivot` を参照）。
 *
 * | 役割 | issue の idx | 本 fixture の idx | 日時 (UTC) | 終値 | 高安 |
 * |---|---:|---:|---|---:|---:|
 * | 山1 | 41 | **329** | 09-03 21:00 | 12,718,980 | 12,807,555 |
 * | 谷（ネックライン） | 46 | **334** | 09-04 02:00 | 12,617,594 | 12,588,132 |
 * | 山2（最終構成点） | 50 | **338** | 09-04 06:00 | 12,639,245 | 12,800,000 |
 * | **再上昇の H ピボット** | **55** | **343** | 09-04 11:00 | **12,711,037** | **12,731,234** |
 * | ブレイク確認 | 56 | **344** | 09-04 12:00 | 12,396,727 | |
 * | 次の谷 | 58 | **346** | 09-04 14:00 | 12,343,265 | 12,302,470 |
 *
 * **実データ C ではこの構造の回帰が取れない。** C の末尾は `2026-09-04T13:00Z` で、
 * idx 55（= C idx 362）の直後 3 本（`swingDepth=3` の確定に必要）が入っていない。
 * 本 fixture が要る理由はそれだけ——`2026-09-05T03:00Z` 以降まで含む窓が必要だった。
 *
 * ## 25% ゾーンとの関係（**既存の再進入チェックでは拾えない**配置）
 *
 * `detectTroughZoneReentry` のゾーンは アンカー 12,807,555（山1 の高値）から
 * パターン高さ 219,423 の 25% 下、つまり下限 **12,752,699**。idx 343（issue の 55）の終値
 * 12,711,037 は**それを 0.3% 下回る**ので再進入とは判定されない。#242 の経路ゲート
 * （`detectPivotBeforeBreakout`）だけがこの形を落とす。
 *
 * **数値は改変しないこと。** 末尾は切っていない（取得時点の直近 365 本そのもの）。
 */

/** fixture 先頭バーの時刻（UTC, ISO8601） */
export const BTC_JPY_1HOUR_2026_09_05_START = '2026-08-21T04:00:00.000Z';

/** fixture 末尾バーの時刻（UTC, ISO8601）。取得時点の最新足で、切り詰めはしていない。 */
export const BTC_JPY_1HOUR_2026_09_05_END_ISO = '2026-09-05T08:00:00.000Z';

